<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('ROLES_GESTIONAR');$in=json_input();
$id=(int)($in['rol_id']??0);$code=strtoupper(preg_replace('/[^A-Z0-9_]+/','_',trim((string)($in['codigo']??''))));$name=trim((string)($in['nombre']??''));$desc=trim((string)($in['descripcion']??''));$scope=in_array(($in['alcance']??''),['GLOBAL','DEPARTAMENTO','JERARQUIA','PROPIO'],true)?$in['alcance']:'PROPIO';$status=in_array(($in['estatus']??''),['ACTIVO','INACTIVO'],true)?$in['estatus']:'ACTIVO';$permCodes=array_values(array_unique(array_filter(array_map('strval',$in['permissions']??[]))));
if($code===''||$name==='')json_response(['ok'=>false,'error'=>'Código y nombre son obligatorios'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$db->begin_transaction();
try{$before=null;if($id>0){$st=$db->prepare("SELECT * FROM rol WHERE rol_id=?");$st->bind_param('i',$id);$st->execute();$before=$st->get_result()->fetch_assoc();$st->close();if($before&&((int)$before['es_sistema']===1)&&!in_array($code,['ADMIN','PRESIDENTE','TESORERIA','DIRECTOR','SUPERVISOR','SUBORDINADO'],true))throw new RuntimeException('No se puede cambiar el código de un rol del sistema');$st=$db->prepare("UPDATE rol SET codigo=?,nombre=?,descripcion=?,alcance=?,estatus=? WHERE rol_id=?");$st->bind_param('sssssi',$code,$name,$desc,$scope,$status,$id);$st->execute();$st->close();}
else{$st=$db->prepare("INSERT INTO rol(codigo,nombre,descripcion,alcance,es_sistema,estatus) VALUES(?,?,?,?,0,?)");$st->bind_param('sssss',$code,$name,$desc,$scope,$status);$st->execute();$id=(int)$st->insert_id;$st->close();}
$st=$db->prepare("DELETE FROM rol_permiso WHERE rol_id=?");$st->bind_param('i',$id);$st->execute();$st->close();if($permCodes){$ph=implode(',',array_fill(0,count($permCodes),'?'));$types=str_repeat('s',count($permCodes));$st=$db->prepare("SELECT permiso_id,codigo FROM permiso WHERE codigo IN ($ph)");$st->bind_param($types,...$permCodes);$st->execute();$rs=$st->get_result();$ids=[];while($r=$rs->fetch_assoc())$ids[]=(int)$r['permiso_id'];$st->close();$st=$db->prepare("INSERT INTO rol_permiso(rol_id,permiso_id) VALUES(?,?)");foreach($ids as $pid){$st->bind_param('ii',$id,$pid);$st->execute();}$st->close();}
audit_log($db,(int)$user['user_id'],$before?'ROL_EDITAR':'ROL_CREAR','ROL',$id,$name,$before,$in);$db->commit();$db->close();json_response(['ok'=>true,'data'=>['rol_id'=>$id]]);}catch(Throwable $e){$db->rollback();$db->close();json_response(['ok'=>false,'error'=>$e->getMessage()],409);}
